<?php
/**
 * Detection of automatically generated order notes.
 *
 * @package DahuOrderNotes
 */

defined( 'ABSPATH' ) || exit;

/**
 * Decides whether an order note was written by a human or generated by code.
 *
 * WooCommerce already marks notes added without a logged-in user with the
 * `system-note` class. The notes this class is concerned with are the ones
 * generated by code *while an administrator is logged in* — changing an order
 * status from the admin screen, for example. Those are attributed to that
 * administrator and are indistinguishable, in the markup, from a note the
 * administrator actually typed.
 *
 * The only reliable signal left is the wording. Rather than hardcoding that
 * wording in one language, the patterns are rebuilt at runtime from
 * WooCommerce's own translatable strings, so the plugin follows whatever
 * locale the shop runs in.
 */
class Dahu_Order_Notes_Detector {

	/**
	 * Compiled regular expressions, built once per request.
	 *
	 * @var string[]|null
	 */
	private static $patterns = null;

	/**
	 * Source strings, exactly as they appear in WooCommerce core.
	 *
	 * Each one is passed through the `woocommerce` text domain at runtime, so
	 * a French shop matches the French wording, a German shop the German one,
	 * and so on. A string WooCommerce no longer uses simply never matches,
	 * which is harmless.
	 *
	 * @var string[]
	 */
	private static $core_templates = array(

		// Status transitions. The first is by far the most common note on any
		// shop, and the one most often signed with a human's name — which is
		// exactly why matching on content matters.
		'Order status changed from %1$s to %2$s.',
		'Order status set to %s.',
		'Order status set to refunded. To return funds to the customer you will need to issue a refund through your payment gateway.',
		'Error during status transition.',
		'Update status event failed.',

		// Stock.
		'Stock levels reduced:',
		'Stock levels increased:',
		'Adjusted stock: %s',
		'Adjusted stock: %s.',
		'Item #%1$s stock increased from %2$s to %3$s.',
		'Unable to reduce stock for item %s.',
		'Unable to restore stock for item %s.',
		'Stock hold of %1$s minutes applied to: %2$s',

		// Line items and coupons, written when an order is edited.
		'Added line items: %s',
		'Deleted %s',
		'Deleted %1$s and adjusted stock (%2$s)',
		'Coupon applied: "%s".',
		'Coupon removed: "%s".',

		// Payment and refunds.
		'Payment complete event failed.',
		'Refunded %1$s - Refund ID: %2$s',
		'Order fully refunded.',

		// Mail and data.
		'Email "%s" failed to send.',
		'Order details manually sent to customer.',
		'Download permissions were reset manually.',
		'Personal data removed.',
	);

	/**
	 * Wordings WooCommerce used to write and no longer does.
	 *
	 * Kept so a shop still running an older WooCommerce is covered. They are
	 * deliberately held apart from the list above, so that "this string is
	 * gone from current WooCommerce" stays a fact about history rather than
	 * looking like drift nobody noticed.
	 *
	 * @var string[]
	 */
	private static $legacy_templates = array(
		'Order partially refunded.',
		'Refunded %1$s%2$s',
	);

	/**
	 * Build — once — the list of compiled patterns.
	 *
	 * @return string[]
	 */
	public static function get_patterns() {

		if ( null !== self::$patterns ) {
			return self::$patterns;
		}

		$patterns = array();

		foreach ( array_merge( self::$core_templates, self::$legacy_templates ) as $template ) {
			// phpcs:ignore WordPress.WP.I18n.TextDomainMismatch -- deliberately reading WooCommerce's own translations.
			$translated = __( $template, 'woocommerce' ); // phpcs:ignore WordPress.WP.I18n.NonSingularStringLiteralText
			$compiled   = self::template_to_regex( $translated );

			if ( $compiled ) {
				$patterns[] = $compiled;
			}

			// A shop may run in English, in which case the translated string
			// equals the source; guard against duplicates.
			if ( $translated !== $template ) {
				$compiled_source = self::template_to_regex( $template );

				if ( $compiled_source ) {
					$patterns[] = $compiled_source;
				}
			}
		}

		foreach ( Dahu_Order_Notes_Settings::get_custom_prefixes() as $prefix ) {
			$patterns[] = '/^' . preg_quote( $prefix, '/' ) . '/i';
		}

		/**
		 * Filters the compiled patterns identifying automatic order notes.
		 *
		 * Each entry must be a complete, valid PCRE pattern.
		 *
		 * @since 2.0.0
		 *
		 * @param string[] $patterns Compiled regular expressions.
		 */
		self::$patterns = (array) apply_filters( 'dahu_order_notes_auto_patterns', array_unique( $patterns ) );

		return self::$patterns;
	}

	/**
	 * Turn a printf-style template into an anchored regular expression.
	 *
	 * Placeholders (%s, %d, %1$s…) become non-greedy wildcards; everything
	 * else is matched literally.
	 *
	 * @param string $template Translated template string.
	 * @return string|false Compiled pattern, or false if the template is unusable.
	 */
	private static function template_to_regex( $template ) {

		$template = trim( (string) $template );

		if ( '' === $template ) {
			return false;
		}

		/*
		 * Drop trailing sentence punctuation. The pattern is anchored at the
		 * START only, so the final character of the template is never needed to
		 * identify the note — and WooCommerce does vary it. The mail failure
		 * note is declared as 'Email "%s" failed to send.' but written as
		 * 'Email "New order" failed to send: Could not instantiate mail
		 * function.', so a pattern insisting on that period matched nothing a
		 * real shop produces. Refund notes have shed their period across
		 * versions the same way.
		 */
		$template = rtrim( $template, " .:;!" );

		if ( '' === $template ) {
			return false;
		}

		// Swap placeholders for a sentinel that survives preg_quote untouched.
		$sentinel = 'DAHUNOTESWILDCARD';
		$stripped = preg_replace( '/%(?:\d+\$)?[sd]/', $sentinel, $template );

		if ( null === $stripped ) {
			return false;
		}

		$quoted = preg_quote( $stripped, '/' );
		$regex  = str_replace( $sentinel, '.*?', $quoted );

		return '/^' . $regex . '/i';
	}

	/**
	 * Normalise note content before matching.
	 *
	 * WooCommerce notes routinely contain HTML and non-breaking spaces — a
	 * French locale puts one before every colon, for instance. Decoding the
	 * entities and flattening every kind of whitespace is what lets one
	 * pattern match regardless of locale typography.
	 *
	 * Anything that is not a string or a number returns an empty string rather
	 * than raising an error. These are public static methods on a class whose
	 * patterns are filterable, so third-party code calls them; casting an
	 * object to string would throw, and it would throw while rendering an order
	 * screen. Returning "not automatic" is the right failure here.
	 *
	 * @param mixed $content Raw note content.
	 * @return string
	 */
	public static function normalise( $content ) {

		if ( ! is_string( $content ) && ! is_numeric( $content ) ) {
			return '';
		}

		$content = wp_strip_all_tags( (string) $content );
		$content = html_entity_decode( $content, ENT_QUOTES, 'UTF-8' );
		$content = preg_replace( '/[\s\x{00A0}]+/u', ' ', $content );

		return trim( (string) $content );
	}

	/**
	 * Is this note content machine-generated?
	 *
	 * Takes the note's CONTENT, not the note object.
	 *
	 * @param mixed $content Raw note content.
	 * @return bool
	 */
	public static function is_automatic( $content ) {

		$content = self::normalise( $content );

		if ( '' === $content ) {
			return false;
		}

		foreach ( self::get_patterns() as $pattern ) {
			if ( @preg_match( $pattern, $content ) === 1 ) { // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged -- a filtered pattern may be malformed; a bad pattern must not break the order screen.
				return true;
			}
		}

		return false;
	}
}
